fun {p} =>
  {
    skipPrefix? := fun s =>
      if h : s.startPos = s.endPos then none
      else if p (s.startPos.get h) = true then some (s.startPos.next h) else none,
    skipPrefixOfNonempty? := fun s h =>
      if p (s.startPos.get ⋯) = true then some (s.startPos.next ⋯) else none,
    startsWith := fun s => if h : s.startPos = s.endPos then false else p (s.startPos.get h) }

