fun {p} =>
  {
    skipSuffix? := fun s =>
      if h : s.endPos = s.startPos then none
      else if p ((s.endPos.prev h).get ⋯) = true then some (s.endPos.prev h) else none,
    skipSuffixOfNonempty? := fun s h =>
      if p ((s.endPos.prev ⋯).get ⋯) = true then some (s.endPos.prev ⋯) else none,
    endsWith := fun s => if h : s.endPos = s.startPos then false else p ((s.endPos.prev h).get ⋯) }

