  [Std.LawfulIteratorLoop α m m] {it : Std.IterM m β} :
  it.length = do
    let __do_lift ← it.step
    match ↑__do_lift.inflate with
      | Std.IterStep.yield it' out => do
        let __do_lift ← it'.length
        pure { down := __do_lift.down + 1 }
      | Std.IterStep.skip it' => do
        let __do_lift ← it'.length
